import "../Styles/StudentRegister.css";
import Footer from "./Footer";
import { Link } from "react-router-dom";
import { useState } from "react";

const StudentRegister = () => {
  const [role, setRole] = useState("student");

  return (
    <div className="register-page">
      <section className="register-section">
        <div className="register-box">
          <h2 className="register-title">
            Create your <span>account</span>
          </h2>
          <p className="register-subtitle">
            Please choose your role to continue and fill in the following:
          </p>

          {/* اختيار النوع */}
          <div className="role-switch">
            <button
              className={role === "student" ? "role-btn active" : "role-btn"}
              onClick={() => setRole("student")}
            >
              Student
            </button>
            <button
              className={role === "company" ? "role-btn active" : "role-btn"}
              onClick={() => setRole("company")}
            >
              Company
            </button>
          </div>

          <form className="register-form">
            <label>Full Name</label>
            <input type="text" placeholder="Aisha Ahmed ..." required />

            <label>Email</label>
            <input type="email" placeholder="you@example.com" required />

            <label>Password</label>
            <input type="password" placeholder="************" required />

            <button type="submit" className="signup-btn">
              Sign up
            </button>
          </form>

          <p className="login-text">
            Already have an account?{" "}
            <Link to="/studentlogin" className="login-link">
              Log in now!
            </Link>
          </p>
        </div>
      </section>

      <Footer />
    </div>
  );
};

export default StudentRegister;
